def chart(vals,area=False,labels=None,maxv=150):
 labs=labels or [f'XX년 {i+1}분기' for i in range(len(vals))];w=620;h=256
 s=f'<svg viewBox="0 0 {w} {h}">'
 for n in range(6 if maxv==100 else 4):
  div=5 if maxv==100 else 3; y=h-n*h/div;s+=f'<line x1="0" y1="{y}" x2="620" y2="{y}" stroke="#d1d1d1"/><text x="-10" y="{y+6}" text-anchor="end" font-size="19">{int(maxv*n/div)}</text>'
 pts=[]
 for i,v in enumerate(vals):
  x=(i+.5)*w/len(vals);y=h-v/maxv*h;pts.append((x,y));
  if not area:s+=f'<path d="M{x-35} {h}V{y+35}a35 35 0 0 1 70 0V{h}Z" fill="#065de5"/>'
  s+=f'<text x="{x}" y="{y-15}" fill="#0661ce" font-size="21" text-anchor="middle">{v}</text><text x="{x}" y="{h+30}" font-size="19" text-anchor="middle">{labs[i]}</text>'
 if area:
  s+=f'<defs><linearGradient id="g" x2="0" y2="1"><stop stop-color="#b6cff5"/><stop offset="1" stop-color="#f8fbff"/></linearGradient></defs><path d="M{pts[0][0]} {h}'+''.join(f'L{x} {y}' for x,y in pts)+f'L{pts[-1][0]} {h}Z" fill="url(#g)"/>'
  s+='<polyline points="'+' '.join(f'{x},{y}' for x,y in pts)+'" fill="none" stroke="#6795d0"/>'
  for x,y in pts:s+=f'<circle cx="{x}" cy="{y}" r="4" fill="#065de5"/>'
 return s+'</svg>'
