def page(d,i):
 k=d['kind']; blue=d.get('blue'); s=f'<section class="kind-{k} {"blue" if blue else ""}"><div class="deco a"></div><div class="deco b"></div><div class="deco c"></div><div class="logo">{logo}</div><div class="corner">Town hall meeting</div>'
 title=d['title'];kick=d['kick'];note=d.get('note','');it=d['items']
 if k=='cover':s+=f'<div class="cover-heading"><p class="kick">{kick}</p><h1>{title}</h1><p class="note">{note}</p></div>'
 elif k in ['statement','message','qa','end']:
  s+=f'<div class="centerbody">'+(f'<div class="centerbrand">{logo}</div>' if k=='statement' else '')+(f'<p class="kick">{kick}</p>' if kick else '')+f'<h1>{title}</h1><p class="note">{note}</p></div>'
 elif k in ['bar','area','position','sequence']:
  s+=f'<div class="side-title"><p class="kick">{kick}</p><h1>{title}</h1><div class="note">{note}</div></div>'
 elif k!='donut':s+=f'<div class="heading"><p class="kick">{kick}</p><h1>{title}</h1>'+(f'<p class="sub">{note}</p>' if k in ['values','steps'] else '')+'</div>'
 if k=='index':
  s+='<div style="position:absolute;left:140px;right:140px;top:305px;display:grid;grid-template-rows:repeat(4,57px);grid-auto-flow:column;gap:20px 40px">'
